@:dox(hide) public static macro function addLine(buf:Expr, args:Array<Expr>):Expr {
		var exprs = [];
		for (arg in args) {
			var expanded = expandInterpolatedString(buf, arg);
			if (expanded != null) {
				exprs = exprs.concat(expanded);
			} else {
				exprs.push(macro $buf.add($arg));
			}
		}
		return macro $b{exprs};
	}
